<template>
  <q-page class="q-pa-lg">
    <div class="row items-center justify-between q-mb-md">
      <div>
        <div class="text-h5 text-weight-bold">
          <q-icon name="settings_input_composite" color="primary" class="q-mr-sm" />
          Cấu hình Đầu ghi NVR & Lưu trữ Video
        </div>
        <div class="text-caption text-grey-6">
          Quản lý kết nối Dahua NVR (WAN/LAN/DDNS) và chu kỳ lưu trữ video trên NAS
        </div>
      </div>
      <q-btn outline color="primary" icon="refresh" label="Tải lại" @click="fetchConfig" />
    </div>

    <div class="row q-col-gutter-lg">
      <!-- NVR Connection Form -->
      <div class="col-12 col-lg-7">
        <q-card>
          <q-card-section class="row items-center justify-between">
            <div class="text-subtitle1 text-weight-bold text-primary">
              <q-icon name="dns" class="q-mr-sm" />
              Thông số Kết nối NVR Dahua
            </div>
            <q-badge :color="form.demo_mode ? 'amber-9' : 'positive'" :label="form.demo_mode ? 'Demo Giả lập' : 'NVR Trực tiếp'" />
          </q-card-section>
          <q-separator />

          <q-card-section>
            <q-form @submit.prevent="saveConfig" class="q-gutter-md">
              <div class="row q-col-gutter-md">
                <div class="col-12 col-md-8">
                  <q-input v-model="form.nvr_host" label="Địa chỉ IP / DDNS NVR *" outlined dense :rules="[v => !!v || 'Bắt buộc']">
                    <template #prepend><q-icon name="public" color="primary" /></template>
                  </q-input>
                </div>
                <div class="col-12 col-md-4">
                  <q-input v-model.number="form.nvr_port" type="number" label="Cổng HTTP/HTTPS *" outlined dense :rules="[v => !!v || 'Bắt buộc']">
                    <template #prepend><q-icon name="router" color="primary" /></template>
                  </q-input>
                </div>
              </div>

              <div class="row q-col-gutter-md">
                <div class="col-12 col-md-4">
                  <q-input v-model.number="form.rtsp_port" type="number" label="Cổng RTSP (554) *" outlined dense>
                    <template #prepend><q-icon name="stream" color="primary" /></template>
                  </q-input>
                </div>
                <div class="col-12 col-md-4">
                  <q-input v-model="form.nvr_user" label="Tài khoản NVR *" outlined dense :rules="[v => !!v || 'Bắt buộc']">
                    <template #prepend><q-icon name="person" color="primary" /></template>
                  </q-input>
                </div>
                <div class="col-12 col-md-4">
                  <q-input v-model="form.nvr_password" :type="showPass ? 'text' : 'password'" label="Mật khẩu NVR" outlined dense>
                    <template #prepend><q-icon name="lock" color="primary" /></template>
                    <template #append>
                      <q-icon :name="showPass ? 'visibility_off' : 'visibility'" class="cursor-pointer" @click="showPass = !showPass" />
                    </template>
                  </q-input>
                </div>
              </div>

              <div class="row items-center q-gutter-md">
                <q-toggle v-model="form.use_https" label="Giao thức bảo mật HTTPS (SSL/TLS)" color="primary" />
                <q-toggle v-model="form.demo_mode" label="Chế độ Demo Giả lập" color="amber-9" />
              </div>

              <!-- Test Result Alert -->
              <div v-if="testResult" class="q-mt-sm">
                <q-banner rounded :class="testResult.success ? 'bg-positive text-white' : 'bg-negative text-white'">
                  <template #avatar>
                    <q-icon :name="testResult.success ? 'check_circle' : 'error'" />
                  </template>
                  <div class="text-weight-bold">{{ testResult.message }}</div>
                  <div v-if="testResult.device_model" class="text-caption q-mt-xs">
                    Model: <b>{{ testResult.device_model }}</b> | Serial: <b>{{ testResult.serial_number }}</b> | Firmware: <b>{{ testResult.firmware }}</b>
                  </div>
                </q-banner>
              </div>

              <div class="row justify-between items-center q-pt-md">
                <q-btn outline color="primary" icon="network_check" label="Kiểm tra kết nối" :loading="testing" @click="testConnection" />
                <q-btn unelevated color="primary" icon="save" label="Lưu Cấu Hình" type="submit" :loading="saving" />
              </div>
            </q-form>
          </q-card-section>
        </q-card>
      </div>

      <!-- Service Status & Retention Purge -->
      <div class="col-12 col-lg-5">
        <q-card class="q-mb-md">
          <q-card-section>
            <div class="text-subtitle1 text-weight-bold text-primary">
              <q-icon name="hub" class="q-mr-sm" />
              Trạng thái Listener Service
            </div>
          </q-card-section>
          <q-separator />
          <q-card-section class="q-gutter-sm">
            <div class="row justify-between items-center">
              <span class="text-grey-7">Dahua Listener Service:</span>
              <q-badge :color="listenerStatus.listener?.is_running ? 'positive' : 'negative'" :label="listenerStatus.listener?.is_running ? 'Online' : 'Offline'" />
            </div>
            <div class="row justify-between items-center">
              <span class="text-grey-7">Hàng đợi cắt clip (Worker):</span>
              <span class="text-weight-bold text-primary">{{ listenerStatus.queue_size || 0 }} clip</span>
            </div>
            <div class="row justify-between items-center">
              <span class="text-grey-7">Bộ nhớ lưu trữ Synology NAS:</span>
              <q-badge color="primary" :label="listenerStatus.nas_health?.backend || 'Local Storage'" />
            </div>
            <div class="q-pt-sm">
              <q-btn outline dense color="primary" icon="refresh" label="Làm mới Service" @click="fetchListener" class="full-width" />
            </div>
          </q-card-section>
        </q-card>

        <q-card>
          <q-card-section>
            <div class="text-subtitle1 text-weight-bold text-amber-9">
              <q-icon name="cleaning_services" class="q-mr-sm" />
              Dọn dẹp Lưu trữ (Retention Purge)
            </div>
          </q-card-section>
          <q-separator />
          <q-card-section>
            <div class="text-caption text-grey-7 q-mb-md">
              Dọn dẹp các clip và dữ liệu đã quá hạn retention để giải phóng dung lượng đĩa.
            </div>
            <div class="row items-center q-col-gutter-sm">
              <div class="col-8">
                <q-input v-model.number="retentionDays" type="number" label="Thời gian giữ (ngày)" outlined dense />
              </div>
              <div class="col-4">
                <q-btn unelevated color="amber-9" text-color="white" icon="delete_sweep" label="Dọn dẹp" class="full-width" @click="confirmPurge" :loading="purging" />
              </div>
            </div>
            <div v-if="purgeResult" class="q-mt-sm text-caption text-positive">
              ✅ Đã dọn dẹp: {{ purgeResult.deleted_events || 0 }} sự kiện, {{ purgeResult.deleted_clips || 0 }} file clip.
            </div>
          </q-card-section>
        </q-card>
      </div>
    </div>
  </q-page>
</template>

<script>
import { defineComponent, ref, reactive, onMounted } from 'vue'
import { useQuasar } from 'quasar'

export default defineComponent({
  name: 'NvrConfig',
  setup () {
    const $q = useQuasar()
    const form = reactive({
      nvr_host: '',
      nvr_port: 80,
      rtsp_port: 554,
      nvr_user: '',
      nvr_password: '',
      use_https: false,
      demo_mode: false,
      abnormal_event_codes: []
    })
    const showPass = ref(false)
    const testing = ref(false)
    const saving = ref(false)
    const testResult = ref(null)

    const listenerStatus = reactive({})
    const retentionDays = ref(30)
    const purging = ref(false)
    const purgeResult = ref(null)

    const fetchConfig = async () => {
      try {
        const res = await fetch('/api/config/nvr')
        if (res.ok) {
          const data = await res.json()
          Object.assign(form, data)
        }
      } catch (err) {
        $q.notify({ type: 'negative', message: 'Lỗi tải cấu hình NVR' })
      }
    }

    const fetchListener = async () => {
      try {
        const res = await fetch('/api/admin/listener-status')
        if (res.ok) {
          const data = await res.json()
          Object.assign(listenerStatus, data)
        }
      } catch (err) {
        console.error(err)
      }
    }

    const testConnection = async () => {
      testing.value = true
      testResult.value = null
      try {
        const res = await fetch('/api/config/nvr/test', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(form)
        })
        const data = await res.json()
        testResult.value = data
        if (data.success) {
          $q.notify({ type: 'positive', message: data.message || 'Kết nối thành công!' })
        } else {
          $q.notify({ type: 'negative', message: data.message || 'Kết nối thất bại!' })
        }
      } catch (err) {
        testResult.value = { success: false, message: 'Lỗi mạng: ' + err.message }
        $q.notify({ type: 'negative', message: testResult.value.message })
      } finally {
        testing.value = false
      }
    }

    const saveConfig = async () => {
      saving.value = true
      try {
        const res = await fetch('/api/config/nvr', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(form)
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.error || data.detail || 'Lỗi lưu NVR')
        $q.notify({ type: 'positive', message: data.message || 'Đã lưu cấu hình NVR!' })
        await fetchConfig()
        await fetchListener()
      } catch (err) {
        $q.notify({ type: 'negative', message: err.message })
      } finally {
        saving.value = false
      }
    }

    const confirmPurge = () => {
      $q.dialog({
        title: 'Xác nhận Dọn rác Lưu trữ',
        message: `Bạn có chắc muốn xóa vĩnh viễn các video cũ hơn ${retentionDays.value} ngày không?`,
        cancel: true,
        persistent: true,
        ok: { label: 'Dọn rác ngay', color: 'amber-9' }
      }).onOk(async () => {
        purging.value = true
        try {
          const res = await fetch(`/api/admin/storage/purge-retention?days=${retentionDays.value}`, { method: 'POST' })
          const data = await res.json()
          purgeResult.value = data
          $q.notify({ type: 'positive', message: `Đã dọn dẹp ${data.deleted_events || 0} sự kiện!` })
        } catch (err) {
          $q.notify({ type: 'negative', message: 'Lỗi dọn rác: ' + err.message })
        } finally {
          purging.value = false
        }
      })
    }

    onMounted(() => {
      fetchConfig()
      fetchListener()
    })

    return {
      form,
      showPass,
      testing,
      saving,
      testResult,
      listenerStatus,
      retentionDays,
      purging,
      purgeResult,
      fetchConfig,
      fetchListener,
      testConnection,
      saveConfig,
      confirmPurge
    }
  }
})
</script>
